# Sync DWH project documents from git (els-git/dwh-work) to this PC.
# Each file is embedded and SHA256-verified. A local file is replaced only when
# its current SHA256 is a version known from git history (or the file is
# absent); otherwise NOTHING is written and the script stops, so local edits
# are never overwritten. Replaced files are backed up first.
# Run in Windows PowerShell 5.1: powershell -ExecutionPolicy Bypass -File <this file>
$ErrorActionPreference = 'Stop'

$Root   = 'C:\Users\elshad.asgarov\Desktop\DWH\dwh'
$Stamp  = Get-Date -Format 'yyyyMMdd_HHmmss'
$Backup = Join-Path $Root "runtime\backup\docs_sync_$Stamp"

$Files = @(
    @{
        Path    = 'docs\DWH_IMPLEMENTATION_ROADMAP.md'
        Sha     = 'AB17F5246BE122F23F455463BB79AA1E6BD1FC715034DB93E50F44763ED26898'
        Known   = @('05FEACEDCCD6ECCE56EFEAF3F0352C23A525A01A9E4743B26E917EF1B3E00A64', '34D3552C16A9B76B2E316DE5B48315EB266119F7A60B7BD3141BDE1CCB4DC8BD', '37CBBA015330C777D9DA596A96AA5863833FFD3CECE6B20B698C10CDE896D748', '9CE6409621DC96C8A9D78043E70F2607041F31F4147EC1C758629AABCF28B13E', 'AB0A9530DBE8C682902B6C8181E2C794EAB936E1EDD93AD2F1C9CC99C6998789', 'E787783A74EAA4DDB85FBD07B3C34FCB3925E429AA7C4B6CF6295CE81BC41EE0')
        Current = ''
        Data    = ''
    },
    @{
        Path    = 'docs\DWH_CURRENT_FUNCTIONALITY.md'
        Sha     = '86BB557F2054055E05C495014112C841D2700791F68BB26CF14FB8BD46C799C7'
        Known   = @('548033CB22A3364C5ED932CBEE63FAD2C0FE9FF9E0089641DD2A42A38C3353D8', '5A84FA15C117F2C6D619537203E3AC5699A47677FF7EE03B8C53B193E082B31A')
        Current = ''
        Data    = ''
    },
    @{
        Path    = 'docs\DWH_I02_04_MIGRATION_TEST_ROLLBACK_PLAN_DRAFT_20261102.md'
        Sha     = '7DFA1157D5829329538FFA9E696C27F2EC59AD08D7DEB3827762AF59F76B07AC'
        Known   = @('5BBF9BEEED89798E687726DC3F2CEA64B7BAAD94C3341ED1E18F1CEB1C6DA108', '60970DB65996A1320EAF873B5F716CCE10CC019A7AFB28904838CA32AB2DBE6C', '6F28B391DBD1F06E03AAD15F8C0834A6ABDB8C2CC22C063A0FA3971478D8F036', '7BCF0CA4444F52658C74210DF270ED928F0F756DA9F23BC5DB3E2FF461F2E999', '8D255936DAB7C8345275ABFD82F20D8214FA06DB0CD2FBBE9E0F5D5476A1B895', 'AEAAC56FA71C834F9CE29C870CD054BBAB014578D1882E0C0D95B9B49538E88A', 'B1A8D1A3A544AE85FF3B21B9A8F9C13145D5090BEF3909A9E340260050C48D6E', 'B856AA4C2DC8F729669386F3DB168717788D4E4CCA783D8EDEB80216FF6C37D2', 'BC889214F05FD2131D8C7FD4DDCD7064E0E8E43D5A3FDCD9ED10F1BC34A63F59', 'DB62562C007BBC78528CE4DEF4F9C024115652DB939C40865C2D4B40F1E158E2')
        Current = ''
        Data    = ''
    },
    @{
        Path    = 'CLAUDE.md'
        Sha     = 'C8B39BDA3A68487FE1A006CB668E4269FABD94A4948DACEC85F38D4F84AE322D'
        Known   = @('3F28B9B83F066A6A620DC05F1EAFB514F9DC9B7E6AAC513B18AD81F906F9987D', '72C78D6B6292386D5D45DE726AF3A9D94CE23299C073C4BA93486A0151291CC8', '83DE70BD8FEEB9B947E02A6B883624824E7EBEC2EF128E9AAA33F0B4DB2364A5', 'DC47C5AF6497EE983477CE462F9A7BCFB5848028CF4FCCB9C14497329C0A393A', 'ED5DA1F7FC9342BEB56F230E812399A67E3A373122A4711E7E92128369F6F54D')
        Current = ''
        Data    = ''
    }
)

if (-not (Test-Path -LiteralPath $Root)) { throw "STOP: project folder not found: $Root" }

# 1. Decide for every file before writing anything.
$plan = @()
foreach ($f in $Files) {
    $bytes = [Convert]::FromBase64String($f.Data)
    $sha = [BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash($bytes)).Replace('-', '')
    if ($sha -ne $f.Sha) { throw "STOP: embedded copy of $($f.Path) is damaged" }
    $target = Join-Path $Root $f.Path
    if (-not (Test-Path -LiteralPath $target)) {
        $action = 'CREATE'
    } else {
        $current = (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash
        if ($current -eq $f.Sha) { $action = 'CURRENT' }
        elseif ($f.Known -contains $current) { $action = 'REPLACE' }
        else { $action = 'UNKNOWN'; $f.Current = $current }
    }
    $plan += [pscustomobject]@{ File = $f; Target = $target; Bytes = $bytes; Action = $action }
}
foreach ($p in $plan) { Write-Host ("{0,-8} {1}" -f $p.Action, $p.File.Path) }
$unknown = @($plan | Where-Object { $_.Action -eq 'UNKNOWN' })
if ($unknown.Count -gt 0) {
    foreach ($u in $unknown) { Write-Host "  local SHA256 $($u.File.Current) is not a known git version: $($u.File.Path)" }
    throw 'STOP: local changes found; nothing was written. Send these files for comparison.'
}

# 2. Back up and write.
foreach ($p in $plan | Where-Object { $_.Action -in 'CREATE', 'REPLACE' }) {
    if ($p.Action -eq 'REPLACE') {
        $copy = Join-Path $Backup $p.File.Path
        New-Item -ItemType Directory -Force -Path (Split-Path $copy) | Out-Null
        Copy-Item -LiteralPath $p.Target -Destination $copy
    } else {
        New-Item -ItemType Directory -Force -Path (Split-Path $p.Target) | Out-Null
    }
    [IO.File]::WriteAllBytes($p.Target, $p.Bytes)
    $check = (Get-FileHash -LiteralPath $p.Target -Algorithm SHA256).Hash
    if ($check -ne $p.File.Sha) { throw "STOP: verification failed for $($p.File.Path); backup in $Backup" }
}

foreach ($p in $plan) { Write-Host ("SHA256 {0} {1}" -f $p.File.Sha, $p.File.Path) }
if (Test-Path -LiteralPath $Backup) { Write-Host "Previous versions: $Backup" }
Write-Host 'DOCS_SYNC_RESULT: PASS'
